class OrderFacade {
  constructor(private repo: OrderRepository) {}

  create(order: Order) {
    this.repo.save(order);
  }

  find(id: string) {
    return this.repo.findById(id);
  }
}

class PriceAdapter {
  constructor(private api: ExternalPriceApi) {}

  async getPrice(itemId: string) {
    console.log('getPrice', itemId);
    return this.api.fetchPrice(itemId);
  }
}

