class UserServiceV1 {
  constructor(private repo: UserRepo) {}
  getName(id: string) { return this.repo.getName(id); }
  getEmail(id: string) { return this.repo.getEmail(id); }
  getRoles(id: string) { return this.repo.getRoles(id); }
}

/* Version B */
class UserServiceV2 {
  constructor(private repo: UserRepo) {}
  getUserSummary(id: string) {
    const u = this.repo.find(id);
    return { name: u.name, email: u.email, roles: u.roles };
  }
}
